cypress_script:
describe('Tool Shop Product Catalogue', () => {
  it('should search for a tool and display results', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('#search-query').type('Hammer');
    cy.get('[data-test="search-submit"]').click();
    cy.url().should('include', 'search=Hammer');
    // Assert that results are displayed (number of results or message can be asserted here)
  });

  it('should not find any tools with invalid search', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('#search-query').type('NonExistingTool');
    cy.get('[data-test="search-submit"]').click();
    // Assert that the URL reflects the search query
    cy.url().should('include', 'search=NonExistingTool');
    // Assert that no results are displayed (number of results or message can be asserted here)
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Tool Shop Product Catalogue', () => {
  test('should search for a tool and display results', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.fill('#search-query', 'Hammer');
    await page.click('[data-test="search-submit"]');
    await expect(page).toHaveURL(/.*search=Hammer/);
    // Assert that results are displayed (number of results or message can be asserted here)
  });

  test('should not find any tools with invalid search', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.fill('#search-query', 'NonExistingTool');
    await page.click('[data-test="search-submit"]');
    // Assert that the URL reflects the search query
    await expect(page).toHaveURL(/.*search=NonExistingTool/);
    // Assert that no results are displayed (number of results or message can be asserted here)
  });
});
